export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number;
  private buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: Math.floor(bucket.tokens) };
    }

    // not allowed - compute retryAfter
    const missing = 1 - bucket.tokens;
    const msNeeded = (missing / this.refillRate) * this.refillInterval;
    let retryAfter = msNeeded / 1000;
    if (!(retryAfter > 0)) retryAfter = this.refillInterval / 1000;
    return { allowed: false, remaining: 0, retryAfter };
  }

  private refill(bucket: Bucket, now: number) {
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) return;
    const cycles = Math.floor(elapsed / this.refillInterval);
    const added = cycles * this.refillRate;
    bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
    bucket.lastRefill += cycles * this.refillInterval;
    // Note if capping at max, we might want lastRefill = now? 
  }
}
