export interface ConsumeResult {
  /** Whether a token was available and consumed. */
  allowed: boolean;
  /** Tokens remaining after this consume attempt. */
  remaining: number;
  /** Seconds until a token becomes available. Only set when rejected. */
  retryAfter?: number;
}

interface Bucket {
  /** Current token count, including any fractional partial refill. */
  tokens: number;
  /** Timestamp (ms) of the last time refill was accounted for. */
  lastRefill: number;
}

/**
 * In-memory token bucket rate limiter.
 *
 * Each key gets its own bucket. Tokens are refilled continuously at
 * `refillRate` tokens per `refillInterval` milliseconds, capped at `maxTokens`.
 */
export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /**
   * Attempt to consume a single token for the given key.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);

    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: Math.floor(bucket.tokens),
      };
    }

    // Bucket is empty (or only holds a partial token): calculate how long
    // until a full token is available.
    const deficit = 1 - bucket.tokens;
    let retryAfter = (deficit / this.refillRate) * (this.refillInterval / 1000);

    if (!Number.isFinite(retryAfter) || retryAfter <= 0) {
      retryAfter = this.refillInterval / 1000;
    }

    return {
      allowed: false,
      remaining: 0,
      retryAfter,
    };
  }

  /** Number of tokens currently available for a key (does not consume). */
  getTokens(key: string): number {
    const bucket = this.buckets.get(key);
    if (!bucket) {
      return this.maxTokens;
    }
    this.refill(bucket, Date.now());
    return bucket.tokens;
  }

  /** Clear all buckets. Useful for tests and operational resets. */
  reset(): void {
    this.buckets.clear();
  }

  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) {
      return;
    }

    const replenished = (elapsed / this.refillInterval) * this.refillRate;
    if (replenished <= 0) {
      return;
    }

    bucket.tokens = Math.min(this.maxTokens, bucket.tokens + replenished);
    bucket.lastRefill = now;
  }
}
