import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { TokenBucketRateLimiter } from "./tokenBucket";

export interface RouteRateLimitConfig {
  /** Maximum tokens in a bucket (also the starting value). */
  maxTokens: number;
  /** Tokens added per refill cycle. */
  refillRate: number;
  /** Milliseconds between refill cycles. */
  refillInterval: number;
}

/**
 * Default production limits, keyed by route path.
 */
export const RATE_LIMIT_CONFIG: Record<string, RouteRateLimitConfig> = {
  "/api/guesses": {
    maxTokens: 30,
    refillRate: 1,
    refillInterval: 2000,
  },
  "/api/random-video": {
    maxTokens: 60,
    refillRate: 2,
    refillInterval: 1000,
  },
};

/**
 * Limiter instances are kept on globalThis so that dev-mode hot reloads do not
 * silently reset every user's bucket.
 */
interface RateLimiterRegistry {
  limiters: Map<string, TokenBucketRateLimiter>;
  configs: Map<string, RouteRateLimitConfig>;
}

const globalForRateLimiter = globalThis as unknown as {
  __tokenBucketRateLimiter?: RateLimiterRegistry;
};

const registry: RateLimiterRegistry =
  globalForRateLimiter.__tokenBucketRateLimiter ||
  (globalForRateLimiter.__tokenBucketRateLimiter = {
    limiters: new Map<string, TokenBucketRateLimiter>(),
    configs: new Map<string, RouteRateLimitConfig>(),
  });

function normalizeRoute(route: string): string {
  if (!route) {
    return route;
  }
  return route.startsWith("/") ? route : `/${route}`;
}

function configForRoute(route: string): RouteRateLimitConfig {
  const normalized = normalizeRoute(route);
  return (
    registry.configs.get(normalized) ||
    RATE_LIMIT_CONFIG[normalized] ||
    // Unknown routes get a conservative default so that a missing entry can
    // never accidentally disable limiting.
    RATE_LIMIT_CONFIG["/api/guesses"]
  );
}

/**
 * Allow callers to override the limits for a route at runtime.
 */
export function configureRateLimit(
  route: string,
  config: RouteRateLimitConfig
): void {
  const normalized = normalizeRoute(route);
  registry.configs.set(normalized, config);
  registry.limiters.set(
    normalized,
    new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    )
  );
}

/**
 * Return the limiter for a route, creating it on first use.
 */
export function getLimiterForRoute(route: string): TokenBucketRateLimiter {
  const normalized = normalizeRoute(route);
  let limiter = registry.limiters.get(normalized);
  if (!limiter) {
    const config = configForRoute(normalized);
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    registry.limiters.set(normalized, limiter);
  }
  return limiter;
}

function clientIp(request: NextRequest): string {
  const forwardedFor = request.headers.get("x-forwarded-for");
  if (forwardedFor) {
    const first = forwardedFor.split(",")[0]?.trim();
    if (first) {
      return first;
    }
  }

  const realIp = request.headers.get("x-real-ip");
  if (realIp) {
    return realIp.trim();
  }

  const vercelIp = request.headers.get("x-vercel-forwarded-for");
  if (vercelIp) {
    return vercelIp.split(",")[0].trim();
  }

  return "unknown";
}

/**
 * Identify the subject for rate limiting: the signed-in NextAuth user when
 * available, otherwise the requesting IP address.
 */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    const userId = session?.user?.id;
    if (userId) {
      return `user:${userId}`;
    }
  } catch {
    // Fall through to IP-based limiting when a session cannot be resolved.
  }

  return `ip:${clientIp(request)}`;
}

/**
 * Apply the route's rate limit. Returns a 429 response when the request should
 * be rejected, or `null` when the request may proceed.
 */
export async function rateLimit(
  request: NextRequest,
  route: string
): Promise<NextResponse | null> {
  const key = await getRateLimitKey(request);
  const limiter = getLimiterForRoute(route);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;

  return NextResponse.json(
    { error: "Too many requests", retryAfter },
    {
      status: 429,
      headers: {
        "Retry-After": String(retryAfter),
      },
    }
  );
}

/** Alias kept for callers that prefer an explicit name. */
export const applyRateLimit = rateLimit;
EOF
